def _slash_modelos(ai, args: str) -> None:
    """Registro de expertos: tabla, agregar (3 modalidades), quitar, on/off."""
    from cognia.experts import (load_registry, remove_expert,
                                render_modelos_table, set_enabled)
    partes = args.strip().split()
    sub = partes[0].lower() if partes else ""
    try:
        if not sub:
            try:
                from node.fleet import fleet_status
                fs = fleet_status()
            except Exception:
                fs = None
            print(render_modelos_table(load_registry(), fs))
        elif sub == "agregar":
            _modelos_agregar_flow(" ".join(partes[1:]))
        elif sub == "quitar" and len(partes) == 2:
            e = remove_expert(partes[1])
            print(f"Experto '{e.id}' quitado.")
        elif sub in ("activar", "desactivar") and len(partes) == 2:
            e = set_enabled(partes[1], sub == "activar")
            print(f"Experto '{e.id}' {'activado' if e.enabled else 'desactivado'}.")
        else:
            print("Uso: /modelos [agregar [peticion] | quitar <id> | "
                  "activar <id> | desactivar <id>]")
    except ValueError as exc:
        print(f"[WARN] {exc}")


def _modelos_agregar_flow(peticion: str = "", input_fn=input,
                          print_fn=print) -> None:
    """Alta interactiva de experto en 3 modalidades (encuesta + forjas).

    1) el usuario elige modelo y Cognia forja el prompt de comportamiento
    2) como 1 + adaptador LoRA de identidad (CPU, via expert_forge)
    3) automatico: el meta-modelo convierte la peticion libre en la spec
    input_fn/print_fn inyectables para tests (patron surveys).
    """
    from cognia.console.surveys import ask_survey
    from cognia.experts.prompt_forge import create_expert_with_prompt

    r = ask_survey(
        "Como quieres crear el experto?",
        ["Elijo el modelo y Cognia escribe su prompt de comportamiento",
         "Como la 1 y ademas Cognia entrena un adaptador LoRA (CPU, tarda unos minutos)",
         "Automatico: Cognia decide todo a partir de mi peticion"],
        multi=False, libre=False, input_fn=input_fn, print_fn=print_fn)
    if not r["selected"]:
        print_fn("Alta cancelada.")
        return
    modalidad = 3 if r["selected"][0].startswith("Automatico") else (
        2 if "LoRA" in r["selected"][0] else 1)

    spec = None
    if modalidad == 3:
        if not peticion:
            peticion = input_fn("Describe el experto que quieres (texto libre) > ").strip()
        if peticion:
            from cognia.experts.meta_maker import make_expert_spec
            print_fn("Consultando al meta-modelo creador de expertos...")
            spec = make_expert_spec(peticion)
        if spec is None:
            print_fn("[WARN] El meta-modelo no esta disponible o no produjo una "
                     "spec valida; sigo con el alta guiada.")

    if spec is None:
        nombre = input_fn("Nombre del experto > ").strip()
        dedicacion = input_fn("A que se dedica (una linea) > ").strip()
        if not nombre or not dedicacion:
            print_fn("Alta cancelada (faltan datos).")
            return
        try:
            from node.fleet import fleet_status
            opciones = [f"{m['key']} ({m['params']}, {m['rol']})"
                        for m in fleet_status() if m["presente"]]
        except Exception:
            opciones = []
        if opciones:
            rm = ask_survey("Que modelo lo atiende?", opciones, multi=False,
                            libre=True, input_fn=input_fn, print_fn=print_fn)
            elegido = (rm["selected"][0].split(" ", 1)[0] if rm["selected"]
                       else (rm["libre"] or "chat-7b").strip())
        else:
            elegido = input_fn("model_key (ej. chat-7b) > ").strip() or "chat-7b"
        slug = "-".join("".join(c if c.isalnum() or c == " " else ""
                                for c in nombre.lower()).split())[:40]
        spec = {"id": slug, "nombre": nombre, "dedicacion": dedicacion,
                "model_key": elegido, "backend": "gguf"}

    print_fn(f"Creando experto '{spec['nombre']}' ({spec['model_key']}) — "
             f"forjando su prompt de comportamiento...")
    exp = create_expert_with_prompt(spec["id"], spec["nombre"],
                                    spec["dedicacion"], spec["model_key"],
                                    spec.get("backend", "gguf"),
                                    print_fn=print_fn)
    print_fn(f"Experto '{exp.id}' creado con prompt extenso. Ver con /modelos")

    if modalidad == 2:
        _entrenar_adapter_experto(exp, print_fn=print_fn)


def _entrenar_adapter_experto(exp, print_fn=print) -> None:
    """Modalidad 2: LoRA de identidad via expert_forge (subprocess, CPU)."""
    import json as _json
    import subprocess as _sp
    from pathlib import Path as _P

    from cognia.experts.identity_dataset import (build_identity_dataset,
                                                 write_dataset_json)
    from cognia.experts.registry import experts_dir, save_adapter_file

    root = _P(__file__).resolve().parent.parent
    if not (root / "expert_forge" / "cli_train.py").is_file():
        print_fn("[WARN] expert_forge no esta en esta instalacion; "
                 "el experto queda solo con prompt (sin adapter).")
        return
    model_dir = _P.home() / ".cognia" / "models_hf" / "qwen2.5-0.5b-instruct"
    if not model_dir.is_dir():
        print_fn("[WARN] falta el modelo base 0.5B HF "
                 "(expert_forge.get_base_model); experto sin adapter.")
        return

    prompt_md = None
    try:
        from cognia.experts.registry import system_prompt_path
        p = system_prompt_path(exp)
        prompt_md = p.read_text(encoding="utf-8") if p and p.is_file() else None
    except Exception:
        pass
    dataset = build_identity_dataset(exp.nombre, exp.dedicacion, prompt_md)
    ds_path = write_dataset_json(dataset,
                                 experts_dir() / exp.id / "identity_dataset.json")
    out_dir = experts_dir() / exp.id / "adapter"
    print_fn(f"Entrenando adaptador LoRA de identidad ({len(dataset)} ejemplos, "
             f"~200 steps CPU; puede tardar varios minutos)...")
    try:
        import sys as _sys
        res = _sp.run(
            [_sys.executable, "-m", "expert_forge.cli_train",
             "--model-dir", str(model_dir), "--dataset-json", str(ds_path),
             "--out-dir", str(out_dir), "--steps", "200", "--seq-len", "384"],
            capture_output=True, text=True, timeout=3600, cwd=str(root),
            encoding="utf-8", errors="replace")
        if res.returncode == 0 and res.stdout.strip():
            info = _json.loads(res.stdout.strip().splitlines()[-1])
            save_adapter_file(exp.id, str(out_dir))
            print_fn(f"Adapter entrenado: loss {info['initial_loss']:.2f} -> "
                     f"{info['final_loss']:.2f} (rank {info['rank']}). "
                     f"Guardado en el registro.")
        else:
            print_fn(f"[WARN] el entrenamiento fallo (exit {res.returncode}); "
                     f"el experto queda solo con prompt. Detalle: "
                     f"{(res.stderr or '')[-200:]}")
    except Exception as exc:
        print_fn(f"[WARN] no se pudo entrenar el adapter: {exc}")


def _slash_perfil(nombre: str) -> None:
    """Aplica el perfil de optimizacion 'cpu' o 'gpu' y muestra el resumen."""
    from cognia.perf_profiles import (apply_profile, profile_summary,
                                      restart_backend_hint)
    try:
        apply_profile(nombre)
    except ValueError as exc:
        print(f"[WARN] {exc}")
        return
    print(profile_summary(nombre))
    hint = restart_backend_hint()
    if hint:
        print(hint)
    # Ofrecer el reinicio del backend en un paso: /cpu reiniciar | /gpu reiniciar
    # mata el llama-server para que tome el perfil recien aplicado.
    print(f"Para reiniciar el backend y aplicarlo: /{nombre} reiniciar")


def _slash_shells(args: str) -> None:
    """Lista shells en background; con id muestra las ultimas lineas de output."""
    from cognia.console.proc_registry import get_output, list_shells
    arg = args.strip()
    if arg:
        try:
            sid = int(arg)
        except ValueError:
            print("Uso: /shells [id]")
            return
        lines = get_output(sid, last_n=30)
        if lines is None:
            print(f"[WARN] No existe el shell #{sid}.")
            return
        for ln in lines:
            print(f"  {ln}")
        return
    shells = list_shells()
    if not shells:
        print("Sin shells en background. Lanzar con: /monitor <comando>")
        return
    for s in shells:
        print(f"  #{s['id']:<3} [{s['status']:<7}] {s['cmd'][:70]}"
              f"  (uptime {s['uptime_s']:.0f}s, {s['tail_lines']} lineas)")


def _slash_shell_kill(args: str) -> None:
    """Termina un shell en background por id."""
    from cognia.console.proc_registry import get_status, kill_shell
    try:
        sid = int(args.strip())
    except ValueError:
        print("Uso: /shell-kill <id>")
        return
    # TRES casos, no dos (2026-08-18). Desde que kill_shell dice la verdad
    # ("False" = sigue vivo), el mensaje de antes convertia "no lo pude matar"
    # en "no existe (o ya termino)" — justo al reves de lo que pasa, y con el
    # proceso todavia agarrado al puerto, al fichero o a la GPU.
    if get_status(sid) is None:
        _print_line(f"[warn_cl]No existe el shell #{sid}.[/warn_cl]")
    elif kill_shell(sid):
        _print_line(f"Shell #{sid} terminado.")
    else:
        _print_line(f"[err_cl]El shell #{sid} SIGUE VIVO tras terminate y "
                    f"kill: matalo a mano (Administrador de tareas) antes de "
                    f"contar con su puerto o sus ficheros.[/err_cl]")


def _slash_monitores(args: str) -> None:
    """Lista/crea/detiene monitores en background."""
    from cognia.console.monitors import (list_monitors, monitor_file_exists,
                                         monitor_output_regex,
                                         monitor_url_healthy, stop_monitor)
    partes = args.strip().split()
    sub = partes[0].lower() if partes else ""
    try:
        if not sub:
            mons = list_monitors()
            if not mons:
                print("Sin monitores. Uso: /monitores [salida <id> <regex> | "
                      "archivo <ruta> | url <url> [caida] | stop <id>]")
                return
            for m in mons:
                print(f"  #{m['id']:<3} [{m['status']:<7}] {m['descripcion'][:70]}")
        elif sub == "salida" and len(partes) >= 3:
            mid = monitor_output_regex(int(partes[1]), " ".join(partes[2:]),
                                       f"regex en shell #{partes[1]}")
            print(f"Monitor #{mid} creado (aviso cuando el shell matchee).")
        elif sub == "archivo" and len(partes) == 2:
            mid = monitor_file_exists(partes[1], f"aparicion de {partes[1]}")
            print(f"Monitor #{mid} creado (aviso cuando exista el archivo).")
        elif sub == "url" and len(partes) >= 2:
            caida = "caida" in partes[2:]
            mid = monitor_url_healthy(partes[1], f"salud de {partes[1]}",
                                      esperar_caida=caida)
            print(f"Monitor #{mid} creado (aviso cuando {'caiga' if caida else 'responda'}).")
        elif sub == "stop" and len(partes) == 2:
            ok = stop_monitor(int(partes[1]))
            print("Monitor detenido." if ok else "[WARN] No existe ese monitor.")
        else:
            print("Uso: /monitores [salida <id> <regex> | archivo <ruta> | "
                  "url <url> [caida] | stop <id>]")
    except Exception as exc:  # noqa: BLE001 — el REPL nunca cae por un monitor
        print(f"[WARN] {exc}")


def _slash_modo_permiso(args: str) -> None:
    """Muestra o cambia el modo de permisos (automatico/manual/bypass)."""
    from cognia.console.permissions import MODES, get_mode, set_mode
    arg = args.strip().lower()
    if not arg:
        print(f"Modo de permisos actual: {get_mode()}")
        print("  automatico  Cognia decide cuando pedir confirmacion (default)")
        print("  manual      pide confirmacion para TODO")
        print("  bypass      no pide nada (acepta todas las acciones)")
        print("Cambiar con: /modo-permiso <modo>")
        return
    try:
        set_mode(arg)
        print(f"Modo de permisos: {arg}")
    except ValueError as exc:
        print(f"[WARN] {exc}  Opciones: {', '.join(MODES)}")


def _slash_velocidad(args: str) -> None:
    """Muestra o cambia el mecanismo de decodificacion (ortogonal a /esfuerzo)."""
    from cognia import velocity
    arg = args.strip().lower()
    if not arg:
        print(velocity.velocity_summary())
        return
    try:
        hint = velocity.set_mode(arg)
    except ValueError as exc:
        # El ValueError con la razon exacta ES el contrato (nunca degradar en silencio)
        print(f"[WARN] {exc}")
        return
    print(f"Modo de velocidad '{arg}' aplicado.")
    if hint:
        print(hint)


def _slash_hibrido(args: str) -> None:
    """Activa/desactiva la politica hibrida de velocidad por operacion."""
    from cognia import velocity
    arg = args.strip().lower()
    if arg in ("on", "off"):
        velocity.set_hybrid(arg == "on")
        print(f"Velocidad hibrida: {arg.upper()}"
              + (" — pensamiento profundo usara 'clasico'; el resto, el modo mas rapido disponible." if arg == "on" else ""))
    elif not arg:
        print(f"Velocidad hibrida: {'ON' if velocity.hybrid_enabled() else 'OFF'}")
        print("Uso: /hibrido on|off  (con /esfuerzo alto, el hibrido siempre elige clasico)")
    else:
        print("Uso: /hibrido on|off")


# ---------------------------------------------------------------------------
# CARRIL DE FONDO: la corrida larga en un hilo, la consola ARBITRADA
# ---------------------------------------------------------------------------
# POR QUE (T4, 2026-08-18): /workflow y /hacer se despachaban INLINE en el
# bucle del REPL, asi que mientras corrian NADIE leia el teclado y la vista de
# agentes no podia existir. Aca vive lo minimo para que la corrida viva en un
# hilo daemon y el hilo PRINCIPAL siga siendo el UNICO dueno de la consola.
#
# LA REGLA QUE MANDA, Y ESTA MEDIDA (spike T4, ConPTY por ctypes = la misma
# maquinaria de Windows Terminal, sondas GetConsoleMode/GetConsoleCursorInfo
# leidas DESDE DENTRO del hijo):
#   un hilo que abre una Application de prompt_toolkit NO VUELVE NUNCA.
#   Se midio cognia.ux.selector.confirmar() desde un hilo en los DOS
#   escenarios posibles y en los dos se colgo para siempre:
#     - con la App de Textual abierta ....... NO VOLVIO (ni al cerrar la App)
#     - con solo el prompt del REPL abierto . NO VOLVIO (la tecla se la comio
#                                             el prompt, que devolvio '')
#   Y estas dos SI funcionan:
#     - hilo -> modal de Textual (call_from_thread + push_screen) . 1229,5 ms
#     - hilo -> despertar el prompt y que conteste el principal ... 1032,9 ms
# Por eso el hilo NUNCA pregunta: delega en quien tenga la consola.

# Centinelas del prompt de espera. Empiezan con \x00 (imposible de teclear) y
# ARRASTRAN la linea que el usuario tenia a medio escribir: app.exit() DESCARTA
# el buffer (medido: 'hola mun' desaparecio) y devolverla como `default=` del
# proximo prompt la conserva entera (medido: volvio intacta).
_FONDO_F2      = "\x00@f2@"
_FONDO_FIN     = "\x00@fin@"
_FONDO_PERMISO = "\x00@permiso@"
# F3 en el prompt: reformular la linea a medio escribir. Sale por centinela por
# el MISMO motivo que F2: llamar al modelo dentro del handler bloquearia el
# event loop de prompt_toolkit; afuera el prompt ya devolvio y no hay ninguna
# Application viva.
_FONDO_MEJORA  = "\x00@mejora@"


# Tope del hilo esperando una respuesta de permiso. Vencido -> DENY, que es el
# default del gate, con aviso visible. Un hilo esperando para siempre es el
# fallo silencioso que este repo persigue.
_ESPERA_PERMISO_S = 600.0

# Ventana para que dos Ctrl-C seguidos en el prompt IDLE signifiquen "salir".
_VENTANA_CTRLC_S = 2.0
_ULTIMO_CTRLC = [0.0]

# Lineas que el usuario tecleo MIENTRAS corria algo: se ejecutan cuando
# termina. Es una lista de MODULO (y no la local de repl()) para que el carril
# de fondo, que vive aca afuera, pueda encolar en ella.
_COLA_ENTRADA: list = []

# La linea que _get_input acaba de devolver, VINO de la cola de inyeccion?
# El enrutador por inferencia, los monitores, las rutinas y el carril de fondo
# empujan por la MISMA lista que las lineas tecleadas, asi que sin esta marca
# no hay forma de distinguirlas. El mejorador de prompts jamas puede tocar una
# linea que genero el sistema: reformular el '/hacer <tarea>' que decidio un
# monitor seria cambiar una orden que el usuario nunca escribio.
_LINEA_INYECTADA = [False]

# Texto con el que arranca el PROXIMO prompt (mecanismo 'default=' de
# prompt_toolkit, el mismo con el que F2 conserva la linea a medio escribir).
# Lo llena la opcion "Editar el mejorado" del menu de mejora.
_PRECARGA_PROMPT = [""]

# Marca de UN SOLO USO: la proxima linea ya paso por el mejorador (F3, "Editar
# el mejorado") o el usuario ya dijo que no (Esc). Sin ella el texto reformulado
# volvia al prompt y al dar Enter salia OTRA VEZ el menu sobre algo ya aprobado
# -- y con el estado en 'auto' se llamaba al modelo una segunda vez para
# reformular la reformulacion. La consume _mejora_aplica.
_MEJORA_YA_DECIDIDA = [False]

_VISTA = {"app": None}          # la App de agentes abierta, o None
_LOCK_FONDO = threading.RLock()
_CORRIDA = None                 # la _Corrida viva, o None


class _Corrida:
    """Una corrida de fondo. UNA por vez: el carril es exclusivo.

    Por que exclusivo: dos corridas comparten _history, _session_log, el cwd y
    el gate de permisos, y ademas el unico slot de :8080. El adaptador de
    workflows ya serializa con cap=2 DENTRO de una corrida; dos corridas encima
    seria pelearse por el mismo slot sin que nadie lo pidiera.
    """

    __slots__ = ("etiqueta", "hilo", "fin", "excepcion", "pedido",
                 "cancelada", "t0")

    def __init__(self, etiqueta: str):
        self.etiqueta = etiqueta
        self.hilo = None
        self.fin = threading.Event()
        self.excepcion = None
        self.pedido = None       # dict del permiso pendiente, o None
        self.cancelada = False
        self.t0 = time.time()


def _corrida_viva():
    """La corrida en curso, o None. Lo leen el gate de permisos y el agente."""
    c = _CORRIDA
    return c if (c is not None and not c.fin.is_set()) else None


def corrida_en_curso() -> bool:
    """Publica, para quien lo necesite sin tocar el privado (tests, barra)."""
    return _corrida_viva() is not None


def control_de_la_corrida() -> dict:
    """El CONTROL de lo que esta corriendo, accesible desde fuera del hilo.

    Devuelve la etiqueta, los segundos, si ya se pidio el corte y las corridas
    de workflow vivas (con su run_id) segun el motor. Es lo que hace que
    "corre en un hilo" no signifique "se fue y no hay forma de tocarlo": con
    el run_id se puede cancelar_agente/decirle/cancelar_corrida por el
    adaptador, que es el mismo puente que usa la vista.
    """
    c = _corrida_viva()
    try:
        from cognia.harness import workflows_adapter as _wf
        vivas = list(_wf.corridas_vivas())
    except Exception:
        vivas = []
    if c is None:
        return {"activa": False, "etiqueta": "", "segundos": 0.0,
                "cancelada": False, "corridas": vivas}
    return {"activa": True, "etiqueta": c.etiqueta,
            "segundos": round(time.time() - c.t0, 1),
            "cancelada": bool(c.cancelada), "corridas": vivas}


def _texto_a_medias() -> str:
    """Lo que el usuario tenia a medio escribir. '' ante cualquier duda."""
    try:
        return _sesion_prompt.app.current_buffer.text or ""
    except Exception:
        return ""


def _despertar_prompt(centinela: str, intentos: int = 200) -> bool:
    """Saca al prompt del bloqueo DESDE OTRO HILO. Nunca lanza.

    MEDIDO: app.exit() tiene que correr en el hilo del event loop de
    prompt_toolkit; llamarla derecho desde el hilo del workflow no despierta
    nada. La via es app.loop.call_soon_threadsafe (Application.loop se setea en
    run_async y vuelve a None al terminar).
      * con el prompt ya abierto: desperto al PRIMER intento y el prompt
        devolvio el centinela a los 2001,7 ms de una corrida de 2,0 s.
      * con el hilo terminando ANTES de que el prompt existiera: 30 intentos de
        10 ms lo cazaron y el prompt bloqueo 11,6 ms. SIN el bucle de reintento
        esa carrera deja al usuario esperando un prompt que ya no llega.
    """
    ses = _sesion_prompt
    if ses is None:
        return False
    for _ in range(max(1, intentos)):
        try:
            app = getattr(ses, "app", None)
            loop = getattr(app, "loop", None)
            if app is not None and loop is not None and app.is_running:
                loop.call_soon_threadsafe(
                    functools.partial(app.exit,
                                      result=centinela + _texto_a_medias()))
                return True
        except Exception:
            return False
        time.sleep(0.01)
    return False


def _mensaje_espera(c):
    """El prompt del carril de fondo: MISMO marco que el de siempre.

    Lo unico que cambia es la palabra, para que se vea que hay algo corriendo
    y cuales son las teclas. Se devuelve un callable porque prompt_toolkit lo
    reevalua en cada redibujado (igual que _mensaje_prompt)."""
    def _msg():
        # P5: el texto de la pista y el color salen de prompt.espera (sin
        # override: las clases cognia/estado de siempre); marco, barra y
        # flecha, del mismo compositor que el prompt normal.
        # P9: el tick de 1 s (refresh_interval=1.0) rearma el barrido con
        # cada_s; el pulso en si lo arranca _esperar_corrida al abrir.
        _rearmar_pulso_prompt(getattr(_sesion_prompt, "app", None))
        linea = _frag_prompt("prompt.espera", "cognia",
                             f" {c.etiqueta} {int(time.time() - c.t0)}s",
                             clase_propia=False)
        pista = _texto_prompt("prompt.espera", "F2 agentes · Ctrl-C corta la corrida")
        linea += _frag_prompt("prompt.espera", "estado", "  " + pista,
                              estado="aviso", clase_propia=False)
        if _estilo_de_prompt("prompt.flecha").visible is not False:
            linea += _frag_prompt("prompt.flecha", "flecha",
                                  _glifo_prompt("prompt.flecha", _FLECHA))
        return FormattedText(_cabecera_prompt(linea))
    return _msg


def _vista_con_corte(base):
    """PantallaAgentes + lo que el REPL necesita de ella. Devuelve la CLASE.

    Es una SUBCLASE y no un parche a cognia/tui/agentes.py porque ese fichero
    es de otra tanda. Cuando alli se cablee ctrl+x ('cancelar la corrida'),
    el binding de aca sobra y se borra.

    Tres cosas se agregan, cada una por una medicion:

    1. CSS_PATH ABSOLUTO. Textual resuelve un CSS_PATH relativo contra
       inspect.getfile(type(self)) (textual/_path.py), que en una subclase
       definida en cli.py daria 'cognia/agentes.tcss' — un fichero que no
       existe y una App que no arranca.
    2. ctrl+c = cortar LA CORRIDA. MEDIDO: dentro de una App de Textual el
       Ctrl-C llega como TECLA normal ('ctrl+c'), no como SIGINT (durante la
       App ENABLE_PROCESSED_INPUT esta apagado, in_mode=512, y conhost nunca
       genera CTRL_C_EVENT); por defecto no hace NADA. Verificado: el binding
       se disparo, la App siguio viva, esc la cerro y los modos volvieron a
       503/7. El pie lo ANUNCIA ("^c Cancelar corrida"): hasta hoy no lo
       nombraba y en cambio prometia un ^x que no hacia nada (ver abajo).
    3. begin_capture_print. MEDIDO: con la App abierta, Textual pone
       redirect_stdout(_PrintCapture) y la pantalla queda limpia (0 lineas de
       suciedad), PERO "tragado" es "perdido": 6 de 18 lineas del hilo no
       aparecieron en ningun lado. Con begin_capture_print(self) en on_mount +
       on_print se recuperan EXACTAS, y se vuelcan al cerrar la vista.
       NO se intenta el otro camino (cambiar sys.stdout/sys.__stdout__ por un
       StringIO para silenciar al hilo): esta MEDIDO que ROMPE Textual — su
       driver de Windows se queda con sys.__stdout__ al construirse, la UI se
       escribe dentro del StringIO y la App nunca se pinta.
    """
    from textual.binding import Binding

    _tcss = Path(sys.modules[base.__module__].__file__).with_name("agentes.tcss")

    # EL PIE NO PUEDE MENTIR (T4, 2026-08-18). La clase base declara
    # ctrl+x -> pendiente('...') con la etiqueta "Cancelar corrida (prox.)":
    # el pie ANUNCIA una tecla que no corta nada y CALLA la que si corta
    # (ctrl+c). Aca se corrige para la vista del REPL, que es la unica que
    # tiene una corrida que cortar.
    # SE COORDINA SOLO con la tanda que esta cableando ctrl+x en
    # cognia/tui/agentes.py: solo se pisa MIENTRAS el binding de la base siga
    # siendo el placeholder 'pendiente'. En cuanto alli haga algo de verdad,
    # esta rama se apaga sola y manda el suyo (Textual resuelve BINDINGS por
    # MRO REEMPLAZANDO la lista de cada tecla, no acumulandola:
    # DOMNode._merge_bindings hace keys[key] = key_bindings).
    _cx = [b for b in (getattr(base, "BINDINGS", None) or [])
           if getattr(b, "key", None) == "ctrl+x"]
    _cx_es_placeholder = bool(_cx) and all(
        str(getattr(b, "action", "")).startswith("pendiente") for b in _cx)

    # Textual fusiona BINDINGS por el MRO: aca solo va lo que se AGREGA.
    # priority=True NO es decoracion: MEDIDO en textual 8.2.8, la Screen por
    # defecto trae su propio ctrl+c -> screen.copy_text (show=False) y en
    # Screen.active_bindings — el mapa del que come el Footer — gana el
    # PRIMERO de la cadena (la screen) salvo que el otro sea prioritario. Sin
    # priority la tecla igual cortaba (el dispatch SI prefiere la del App:
    # medido, action_cortar_corrida disparo), pero el pie NO la nombraba, que
    # es justo la mitad del bug que se viene a arreglar.
    # Y la ETIQUETA depende de si la base ya cableo ctrl+x. A las 03:11 del
    # 2026-08-18 lo cableo: su action_cancelar_corrida corta por el MOTOR la
    # corrida PINTADA y ANTES PREGUNTA (ConfirmModal). El ^c de aca corta la
    # corrida DEL REPL y corta YA, sin preguntar. Con las dos teclas rotuladas
    # "Cancelar corrida" el pie volvia a mentir por otra puerta: dos teclas,
    # el mismo cartel, dos comportamientos. Se distingue por el VERBO, y
    # "Cortar la corrida" es ademas la palabra exacta que ya usa el prompt de
    # espera ("Ctrl-C corta la corrida"), asi que los dos carteles del REPL
    # dicen lo mismo. Si la base vuelve al placeholder, vuelve el cartel viejo.
    _rotulo_cc = "Cortar la corrida" if not _cx_es_placeholder else "Cancelar corrida"
    _bindings = [Binding("ctrl+c", "cortar_corrida", _rotulo_cc,
                         priority=True)]
    if _cx_es_placeholder:
        # Alias oculto: la tecla que la base prometia ahora HACE lo que decia,
        # pero el pie nombra una sola vez la accion (y nombra ^c, que es la
        # misma tecla que anuncia el prompt de espera del REPL).
        _bindings.append(Binding("ctrl+x", "cortar_corrida", "Cancelar corrida",
                                 show=False))

    class _VistaAgentesREPL(base):
        CSS_PATH = str(_tcss)
        BINDINGS = _bindings

        def __init__(self, *a, **kw):
            super().__init__(*a, **kw)
            self.lineas_tragadas: list = []

        def on_mount(self) -> None:
            super().on_mount()
            # stdout Y stderr: el hilo puede escribir por los dos.
            try:
                self.begin_capture_print(self)
            except Exception as exc:
                _aviso_degradado("cli.vista.capturar",
                                 f"{type(exc).__name__}: {exc}")

        def on_print(self, event) -> None:
            texto = getattr(event, "text", "")
            if texto:
                self.lineas_tragadas.append(texto)

        def action_cortar_corrida(self) -> None:
            linea = _cancelar_corrida(_corrida_viva(), callado=True)
            try:
                self.notify(linea, title="Ctrl-C", severity="warning",
                            timeout=5)
            except Exception:
                pass

    return _VistaAgentesREPL


def _abrir_vista_agentes() -> None:
    """Abre la pantalla de agentes y vuelve al REPL al salir.

    MEDIDO (spike T4, 7 escenarios): Textual entra y sale de la pantalla
    alterna con ESC[?1049h/l balanceados 1/1, cero ESC[3J (el scrollback de
    antes sigue arriba) y devuelve los modos EXACTOS: in 503 -> 512 dentro de
    la App -> 503 al salir, out 7 estable, cursor visible.

    Se abre AFUERA del bucle de prompt_toolkit a proposito (el keybinding de F2
    solo sale con un centinela): anidar el event loop de Textual dentro del de
    prompt_toolkit es el modo de fallo que este diseno evita.

    Degrada con AVISO, nunca con traceback: la vista la construye otra tanda y
    puede no existir todavia.
    """
    try:
        from cognia.tui.agentes import PantallaAgentes
    except Exception as exc:
        _print_line(f"[warn_cl]La vista de agentes no esta disponible "
                    f"({_escape(type(exc).__name__)}: "
                    f"{_escape(str(exc))}). La corrida sigue.[/warn_cl]")
        _aviso_degradado("cli.vista.import", f"{type(exc).__name__}: {exc}")
        return
    try:
        app = _vista_con_corte(PantallaAgentes)()
    except Exception as exc:
        _print_line(f"[warn_cl]No pude construir la vista de agentes "
                    f"({_escape(type(exc).__name__)}: "
                    f"{_escape(str(exc))}).[/warn_cl]")
        _aviso_degradado("cli.vista.construir", f"{type(exc).__name__}: {exc}")
        return
    _VISTA["app"] = app
    try:
        app.run()
    except Exception as exc:
        _print_line(f"[warn_cl]La vista de agentes se cerro con un fallo: "
                    f"{_escape(str(exc))}[/warn_cl]")
        _aviso_degradado("cli.vista.run", f"{type(exc).__name__}: {exc}")
    finally:
        _VISTA["app"] = None
        _volcar_lineas_tragadas(app)


def _volcar_lineas_tragadas(app) -> None:
    """Lo que el hilo imprimio con la vista abierta, de vuelta en pantalla.

    Textual TRAGA los print() de fondo (redirect_stdout a _PrintCapture) y sin
    begin_capture_print los DESCARTA — medido: 6 de 18 lineas desaparecidas.
    Se escriben tal cual (ya traen el ANSI de rich) al sys.stdout del momento,
    NUNCA a sys.__stdout__: el sink del movil es el que decide por tty, y este
    volcado es texto para el humano que acaba de cerrar la vista.
    """
    lineas = list(getattr(app, "lineas_tragadas", None) or [])
    if not lineas:
        return
    try:
        _print_line(f"[info_dim]— {len(lineas)} linea(s) que la vista habia "
                    f"tragado —[/info_dim]")
        sys.stdout.write("".join(lineas))
        if not lineas[-1].endswith("\n"):
            sys.stdout.write("\n")
        sys.stdout.flush()
    except Exception as exc:
        _aviso_degradado("cli.vista.volcado", f"{type(exc).__name__}: {exc}")


def _cancelar_corrida(c, callado: bool = False) -> str:
    """Ctrl-C = cortar LA CORRIDA, jamas el REPL. Devuelve la linea a mostrar.

    Limite HONESTO, declarado porque cambia lo que el usuario puede esperar:
      * /workflow SI se corta de verdad: el motor tiene cancelacion cooperativa
        por agente (workflows_adapter.cancelar_corrida -> el motor) y el
        envelope vuelve con `cancelados`>0 y el texto YA PAGADO adentro.
      * /hacer se corta AL TERMINAR EL PASO EN CURSO: el bucle del agente no
        tenia ningun hook de cancelacion y ahora lo comprueba entre pasos. Una
        tool larga (un build, un subprocess) NO se interrumpe: termina y ahi
        corta.
    Se usa cancelar_corrida("") = todas las corridas vivas, y es correcto
    porque el carril de fondo es EXCLUSIVO: solo hay una.
    """
    if c is None:
        return "no hay corrida que cortar"
    c.cancelada = True
    partes = []
    try:
        from cognia.harness import workflows_adapter as _wf
        env = _wf.cancelar_corrida("", "el usuario corto con Ctrl-C")
        partes.append(f"{int(env.get('agentes', 0) or 0)} agente(s) alcanzado(s)")
    except Exception as exc:
        partes.append(f"el motor de workflows no acepto el corte ({exc})")
    linea = ("corte pedido: " + "; ".join(partes)
             + ". El paso en curso termina antes de cerrar.")
    if not callado:
        _print_line(f"[warn_cl]Ctrl-C: {_escape(linea)} "
                    f"El REPL sigue vivo.[/warn_cl]")
    return linea


def _tomar_pedido(c):
    """Se LLEVA el permiso pendiente de la corrida (o None). Bajo el lock.

    Quien se lo lleva es el unico que puede contestarlo: sin esto, el hilo que
    lo puso podia retirarlo (su _despertar_prompt fallo y se iba a la 2a
    pasada) mientras el principal ya lo estaba preguntando, y la respuesta del
    usuario se perdia contra un pedido que ya no existia."""
    with _LOCK_FONDO:
        p = c.pedido
        c.pedido = None
    return p


def _retirar_pedido(c, p) -> bool:
    """True si el pedido `p` seguia puesto y lo retiro quien lo pidio.

    False = otro (el principal) ya se lo llevo y esta preguntando: hay que
    esperar SU respuesta, no montar un segundo pedido."""
    with _LOCK_FONDO:
        if c.pedido is p:
            c.pedido = None
            return True
    return False


def _atender_permiso(c) -> None:
    """El hilo PRINCIPAL contesta el permiso que pidio el hilo de la corrida.

    Aca la consola es NUESTRA, asi que se llama al selector de siempre: el
    mismo menu con flechas, el mismo texto plano para los pipes, el mismo
    default."""
    p = _tomar_pedido(c)
    if not p:
        return
    try:
        p["resp"] = _preguntar_en_consola(p["kind"], p["detalle"])
    except KeyboardInterrupt:
        # Ctrl-C JUSTO en la ventana entre que el prompt devolvio el centinela
        # y el selector toma el teclado: sin este except la excepcion sube por
        # _esperar_corrida -> _lanzar_en_fondo -> el dispatch del REPL, que NO
        # la atrapa (el except KeyboardInterrupt del bucle principal solo
        # envuelve _get_input), y el REPL se muere con la corrida viva. Se
        # deniega, que es lo MISMO que ya hacen las dos ramas de
        # _preguntar_en_consola (selector: binding c-c -> False; input():
        # except KeyboardInterrupt -> False), y la corrida sigue.
        p["resp"] = False
        _print_line("[warn_cl]Ctrl-C durante el permiso: la accion se DENIEGA. "
                    "La corrida sigue (Ctrl-C otra vez para cortarla).[/warn_cl]")
    except Exception as exc:
        p["resp"] = False
        _aviso_degradado("cli.permiso.consola", f"{type(exc).__name__}: {exc}")
    finally:
        p["listo"].set()
    if p.get("vencido"):
        # El hilo dejo de esperar antes de que el usuario contestara: decirlo.
        # Sin esto, un "si" tecleado tarde se traga en silencio y el usuario
        # queda creyendo que autorizo algo que ya se denego.
        _print_line(f"[warn_cl]La respuesta llego tarde: el hilo dejo de "
                    f"esperar a los {_ESPERA_PERMISO_S:.0f}s y la accion ya se "
                    f"denego. Si hace falta, pedila de nuevo.[/warn_cl]")


def _permiso_en_vista(app, kind: str, detalle: str):
    """El permiso preguntado DENTRO de la vista. None si no se pudo.

    MEDIDO: True en 1.229,5 ms, la App siguio sana y los modos volvieron a
    503/7. Se usa push_screen CON CALLBACK (y no push_screen_wait): el wait
    exige un worker de Textual y quien pregunta es un threading.Thread pelado
    — pedirselo lanza NoActiveWorker."""
    try:
        from cognia.tui.permiso import PantallaPermiso
    except Exception as exc:
        _aviso_degradado("cli.permiso.modal", f"{type(exc).__name__}: {exc}")
        return None
    listo = threading.Event()
    caja = {}

    def _cb(valor):
        caja["v"] = bool(valor)
        listo.set()

    def _empujar():
        app.push_screen(PantallaPermiso(kind, detalle), _cb)

    try:
        app.call_from_thread(_empujar)
    except Exception as exc:
        _aviso_degradado("cli.permiso.post", f"{type(exc).__name__}: {exc}")
        return None
    # Espera CON PULSO: si el usuario cierra la vista con el modal abierto, el
    # callback no llega nunca y quedarse 600 s seria colgar al agente igual que
    # el bug que este codigo viene a arreglar. Al morir la App se devuelve None
    # y el enrutador reintenta por el prompt.
    limite = time.time() + _ESPERA_PERMISO_S
    while time.time() < limite:
        if listo.wait(0.25):
            return caja.get("v", False)
        if not getattr(app, "is_running", False):
            return None
    _aviso_degradado("cli.permiso.timeout_vista",
                     f"{_ESPERA_PERMISO_S:.0f}s sin respuesta: se deniega")
    return False


def _preguntar_desde_hilo(kind: str, detalle: str):
    """La pregunta del hilo, contestada por el DUENO de la consola.

    True/False, o None si no hay a quien delegarla. Dos pasadas porque la
    vista se puede abrir o cerrar justo en el medio.

    MEDIDO (2026-08-18): vista abierta -> modal arriba en 10,2 ms y respuesta
    en 10,9 ms; vista cerrada con el prompt de espera abierto -> 1,0 ms; el
    usuario cierra la vista con el modal arriba -> el permiso se RESCATA por
    el prompt en 262,9 ms (el pulso de 250 ms de _permiso_en_vista).
    """
    for _ in range(2):
        app = _VISTA.get("app")
        if app is not None and getattr(app, "is_running", False):
            r = _permiso_en_vista(app, kind, detalle)
            if r is not None:
                return r
        c = _corrida_viva()
        if c is None:
            return None
        p = {"kind": kind, "detalle": detalle,
             "listo": threading.Event(), "resp": False}
        with _LOCK_FONDO:
            c.pedido = p
        if not _despertar_prompt(_FONDO_PERMISO):
            if _retirar_pedido(c, p):
                continue                   # nadie lo tomo: 2a pasada (vista?)
            # El principal se lo llevo mientras reintentabamos (lo vio al
            # ciclar en _esperar_corrida): SU respuesta es la buena. Montar un
            # segundo pedido aca preguntaria dos veces lo mismo.
        if not p["listo"].wait(_ESPERA_PERMISO_S):
            p["vencido"] = True            # lo lee _atender_permiso si contesta tarde
            _retirar_pedido(c, p)
            _aviso_degradado(
                "cli.permiso.timeout_prompt",
                f"{_ESPERA_PERMISO_S:.0f}s sin respuesta: se deniega")
            return False
        return bool(p["resp"])
    return None


def _sin_carril() -> bool:
    """COGNIA_SIN_FONDO=1 devuelve el REPL al despacho INLINE de siempre.

    Es la salida de emergencia y el brazo de control del e2e: con esto se
    compara, linea a linea, que la salida impresa del carril de fondo es la
    MISMA que la de hoy."""
    return os.environ.get("COGNIA_SIN_FONDO", "") == "1"


def _lanzar_en_fondo(etiqueta: str, fn, *args, **kw) -> bool:
    """Corre fn(*args) en un hilo daemon y espera con el TECLADO VIVO.

    Devuelve False cuando no hay carril de fondo posible (sin PromptSession:
    pipes, CI, subprocess; o COGNIA_SIN_FONDO=1) y el caller tiene que seguir
    por el camino INLINE de siempre — ese camino queda BYTE-IDENTICO a hoy,
    que es el contrato.
    """
    global _CORRIDA
    if _sesion_prompt is None or _sin_carril():
        return False
    with _LOCK_FONDO:
        if _corrida_viva() is not None:
            _print_line(f"[warn_cl]Ya hay una corrida en curso "
                        f"({_escape(_CORRIDA.etiqueta)}). F2 para verla, "
                        f"Ctrl-C para cortarla.[/warn_cl]")
            return True                    # atendido: NO ejecutar tambien inline
        c = _Corrida(etiqueta)
        _CORRIDA = c

    # El spinner de rich (Live) y el prompt no pueden compartir la consola.
    # MEDIDO con el prompt abierto: un status() de 3,0 s dejo 14 lineas
    # 'pensando…' en el scrollback (~4,7 lineas/s) y CERO secuencias ESC[1A /
    # ESC[2K — el Live no reescribe en sitio, cada frame pasa por el
    # redibujado de patch_stdout. En 3 minutos de /hacer son ~850 lineas de
    # basura. En el carril de fondo el spinner se apaga; la actividad se mira
    # con F2. renderer._consola_interactiva() lee COGNIA_SPINNER a CALL-TIME,
    # asi que esto surte efecto sin recargar nada, y se restaura al terminar.
    _spinner_antes = os.environ.get("COGNIA_SPINNER")
    os.environ["COGNIA_SPINNER"] = "0"

    def _correr():
        try:
            fn(*args, **kw)
        except BaseException as exc:       # noqa: BLE001 — el hilo no muere mudo
            c.excepcion = exc
        finally:
            c.fin.set()
            _despertar_prompt(_FONDO_FIN)

    c.hilo = threading.Thread(target=_correr, name=f"cognia-{etiqueta}",
                              daemon=True)
    try:
        try:
            c.hilo.start()
        except RuntimeError as exc:
            # Sin hilo no hay carril. Se devuelve False y el caller ejecuta
            # INLINE, que es exactamente el camino de siempre: mejor lento que
            # con una corrida que nadie arranco. El finally limpia el estado.
            c.fin.set()
            _aviso_degradado("cli.fondo.hilo", f"{type(exc).__name__}: {exc}")
            return False
        # EL HUECO DEL CTRL-C, cerrado (T4, 2026-08-18). RAZONADO, no medido:
        # el ConPTY del spike no entrega CTRL_C_EVENT en modo cocido, asi que
        # aca no se puede tocar la tecla de verdad. El razonamiento:
        #   en Windows un Ctrl-C llega como CTRL_C_EVENT y CPython levanta el
        #   KeyboardInterrupt en el HILO PRINCIPAL en el limite de bytecode
        #   siguiente — o sea, en CUALQUIER punto de este camino, no solo
        #   dentro de prompt(). El except de _esperar_corrida cubre SOLO la
        #   llamada a prompt(); todo lo demas que corre entre medias (abrir la
        #   vista con F2, volcar las lineas tragadas, atender un permiso,
        #   encolar una linea, el propio arranque del hilo) quedaba al aire, y
        #   el bucle principal del REPL NO atrapa KeyboardInterrupt en el
        #   dispatch (su except envuelve solo _get_input). Resultado: el REPL
        #   se moria con la corrida daemon viva — justo lo que este diseno
        #   viene a impedir.
        # REPRODUCIDO en pytest haciendo que _abrir_vista_agentes lance
        # KeyboardInterrupt (el centinela F2 la llama desde _esperar_corrida,
        # fuera del prompt): sin este bucle la excepcion SALIA de
        # _lanzar_en_fondo. Ver tests/test_cli_carril_fondo.py.
        # El `if` va DENTRO del try a proposito: asi el unico bytecode que
        # queda fuera de la proteccion es el salto del while.
        while True:
            try:
                if c.fin.is_set():
                    break
                _esperar_corrida(c)
            except KeyboardInterrupt:
                _cancelar_corrida(c)
    finally:
        with _LOCK_FONDO:
            _CORRIDA = None
        if _spinner_antes is None:
            os.environ.pop("COGNIA_SPINNER", None)
        else:
            os.environ["COGNIA_SPINNER"] = _spinner_antes
    if c.excepcion is not None:
        _print_line(f"[err_cl]{_escape(type(c.excepcion).__name__)}: "
                    f"{_escape(str(c.excepcion))}[/err_cl]")
        _aviso_degradado("cli.fondo",
                         f"{type(c.excepcion).__name__}: {c.excepcion}")
    return True


def _esperar_corrida(c) -> None:
    """El hilo PRINCIPAL mientras la corrida vive: teclado vivo, consola suya.

    Cada decision con su medicion:
      * patch_stdout(raw=True): sin raw, prompt_toolkit reemplaza cada ESC por
        '?' y todo el color de rich sale mutilado (10 de 10 secuencias rotas);
        con raw=True, 0 rotas. Y con el, la linea a medio escribir se redibuja
        INTACTA cuando el hilo imprime — es lo unico que lo conserva (con
        msvcrt la linea sale pegada al texto del trabajo).
      * el prompt bloquea DE VERDAD: 0,00 % de CPU en reposo (msvcrt: 0,47 %)
        y la tecla llega en 0,52 ms de mediana (msvcrt: 5,59 ms).
      * erase_when_done: el prompt de espera se BORRA al cerrarse, para que el
        scrollback que queda sea EXACTAMENTE el de hoy. Sin esto, cada ciclo
        de espera dejaria su marco y su reloj pegados en el historial.
      * refresh_interval=1.0 es lo que hace correr el reloj del prompt, y solo
        mientras hay corrida.
    """
    pendiente = ""
    app = getattr(_sesion_prompt, "app", None)
    _borrar_antes = getattr(app, "erase_when_done", False)
    try:
        if app is not None:
            app.erase_when_done = True
        while True:
            # El pedido de permiso se comprueba ACA, y no solo cuando llega el
            # centinela, porque el centinela se PIERDE: si el usuario aprieta
            # Enter (o F2) en el mismo instante en que el hilo llama a
            # app.exit, el prompt devuelve la linea tecleada y el centinela se
            # descarta ('Return value already set'). MEDIDO con el wake
            # perdido: el hilo esperaba el tope ENTERO (3.021,9 ms con el tope
            # bajado a 3 s; 600 s en produccion) con el dueno de la consola
            # sentado en el prompt de espera, y terminaba denegando. Con esta
            # comprobacion lo atiende en el ciclo siguiente.
            if c.pedido is not None:
                _atender_permiso(c)
                continue
            if c.fin.is_set():
                return
            try:
                # P9 (E3): prompt.espera anima con el MISMO pulso finito que
                # el prompt idle; refresh_interval se queda en 1.0 (con 1/fps
                # se midio 17% de CPU durante toda la corrida).
                _arrancar_pulso_prompt(app, _IDS_PULSO_ESPERA)
                try:
                    with patch_stdout(raw=True):
                        r = _sesion_prompt.prompt(_mensaje_espera(c),
                                                  default=pendiente,
                                                  refresh_interval=1.0)
                finally:
                    _cerrar_pulso_prompt()
                pendiente = ""
            except KeyboardInterrupt:
                # Ctrl-C EN EL PROMPT: prompt_toolkit lo entrega como excepcion
                # y corta SOLO la linea (medido). Aca corta LA CORRIDA y sigue
                # esperando a que el hilo cierre: matar el REPL con trabajo
                # vivo es justo lo que este diseno viene a impedir.
                _cancelar_corrida(c)
                continue
            except EOFError:
                _cancelar_corrida(c)
                _print_line("[warn_cl]Ctrl-D con una corrida viva: se pidio el "
                            "corte y se espera a que cierre.[/warn_cl]")
                c.fin.wait()
                return
            except Exception as exc:
                # Sin consola no hay espera interactiva posible: se degrada a
                # bloquear seco, que es el comportamiento de hoy.
                _aviso_degradado("cli.fondo.espera",
                                 f"{type(exc).__name__}: {exc}")
                c.fin.wait()
                return

            if r.startswith(_FONDO_FIN):
                pendiente = r[len(_FONDO_FIN):]
                continue                   # el 'if' de arriba decide si cierra
            if r.startswith(_FONDO_PERMISO):
                pendiente = r[len(_FONDO_PERMISO):]
                _atender_permiso(c)
                continue
            if r.startswith(_FONDO_F2):
                pendiente = r[len(_FONDO_F2):]
                _abrir_vista_agentes()
                continue
            if r.startswith(_FONDO_MEJORA):
                # F3 vive en la MISMA sesion, asi que tambien llega aca. Sin
                # esta rama el centinela caia al 'anotado en cola' de abajo
                # ('\x00' NO es whitespace: strip() no lo quita) y el turno
                # entero viajaba al modelo con el NUL pegado delante.
                # NO se reformula con una corrida viva a proposito: el
                # mejorador tarda cientos de ms contra el UNICO slot que la
                # corrida esta usando, y este bucle es tambien el que atiende
                # los pedidos de permiso. La linea vuelve intacta al prompt.
                pendiente = r[len(_FONDO_MEJORA):]
                _print_line("[info_dim]F3 no mejora mientras hay una corrida "
                            "(el modelo esta ocupado): la linea sigue en el "
                            "prompt.[/info_dim]")
                continue
            linea = (r or "").strip()
            if linea:
                # Se ANOTA, no se ejecuta: dos turnos a la vez comparten
                # _history, el cwd y el unico slot de :8080. El proximo
                # _get_input la devuelve y entra por el MISMO dispatch.
                _COLA_ENTRADA.append(linea)
                _print_line(f"[info_dim]anotado ({len(_COLA_ENTRADA)} en cola): "
                            f"se ejecuta cuando termine "
                            f"{_escape(c.etiqueta)}.[/info_dim]")
    finally:
        if app is not None:
            app.erase_when_done = _borrar_antes


def _corte_pedido() -> bool:
    """True si el usuario pidio cortar la corrida que esta en curso.

    Lo consultan el bucle legacy del agente (cli.py) y el nativo
    (cognia/agent/loop.py, via ctx['_cancelado']). Se comprueba ENTRE pasos:
    una tool larga (un build, un subprocess) no se interrumpe — termina y ahi
    corta. Eso esta dicho en la linea que se imprime, no escondido.

    Tambien True con la bandera de la interrupcion REMOTA levantada
    (_INTERRUPCION_PENDIENTE): el agente inline la consulta entre pasos y
    corta en el siguiente sin esperar a que el KeyboardInterrupt se procese
    (o aunque algun except intermedio se lo haya comido)."""
    if _INTERRUPCION_PENDIENTE[0]:
        return True
    c = _corrida_viva()
    return c is not None and bool(c.cancelada)


# ---------------------------------------------------------------------------
# Paridad REMOTA (2026-08-24): interrumpir desde el movil y multilinea por pipe.
# ---------------------------------------------------------------------------

# True mientras el hilo principal esta BLOQUEADO leyendo la siguiente linea del
# usuario. Lo consulta el handler de interrupcion remota: una senal que llega
# con el REPL ocioso no tiene nada que cortar, y si el handler lanzara igual,
# el KeyboardInterrupt caeria en el `except` que rodea a _get_input y se
# COMERIA el mensaje recien leido ("linea cancelada"). Medido 2026-08-24 con
# un hijo bloqueado en input() sobre un pipe: el handler de Python corre
# DESPUES de que input() devuelve (la senal solo dispara el flag en C; el
# eval loop lo ve al volver), o sea con este flag todavia en True — por eso
# el flag se baja en un finally y no antes de la lectura.
_EN_PROMPT = [False]
_INTERRUPCIONES_REMOTAS = [0]     # cuantas senales llegaron (diagnostico)
# Bandera COOPERATIVA de la interrupcion remota. La pone el handler nativo de
# consola (Windows, hilo propio del sistema: corre EN EL ACTO) o el handler de
# Python (al siguiente bytecode); la consulta _corte_pedido() entre pasos del
# agente y la baja el bucle del REPL al empezar cada turno. POR QUE: medido
# 2026-08-25 (revisores, hijo real): la senal llega en <10 ms pero el
# KeyboardInterrupt solo se procesa al VOLVER de la llamada C bloqueada (el
# urlopen al backend: 96-155 s con el 27B). Con la bandera, el agente no da
# un paso mas despues de esa llamada aunque algun `except` intermedio se
# hubiera comido el KeyboardInterrupt.
_INTERRUPCION_PENDIENTE = [False]
_CTRL_HANDLER_NATIVO = [None]     # referencia viva del callback ctypes (GC)


def _interrupcion_remota_handler(signum=None, frame=None) -> None:
    """Handler de SIGBREAK (Windows) / SIGINT (POSIX) bajo COGNIA_REMOTO=1.

    Corre en el hilo principal entre dos bytecodes. Lanza KeyboardInterrupt
    para caer en los `except KeyboardInterrupt` que el REPL YA tiene: el del
    fast-path de chat (corta el stream, 'turno cortado', vuelve al prompt), el
    del camino articulado, el de _esperar_corrida (cancela la corrida de
    fondo), los que envuelven al agente inline (/hacer y la accion inferida)
    y, desde 2026-08-25, el que envuelve la ITERACION ENTERA del bucle del
    REPL (_repl_iteracion_interrumpida): sin ese ultimo, la senal recibida
    entre el input() y el primer token (investigacion previa de confianza,
    enrutador por inferencia, mejora de prompt) MATABA el REPL. Ocioso (en el
    prompt) NO lanza: ver _EN_PROMPT.

    Emite ANTES de lanzar: el Aviso viaja por el bus (sink stdout -> movil) y
    el renderer local lo pinta; emitir() es no-lanzante por contrato y el
    raise queda fuera de cualquier try para que nada lo trague."""
    _INTERRUPCIONES_REMOTAS[0] += 1
    ocioso = bool(_EN_PROMPT[0])
    try:
        from cognia.ux import events as _ev
        if ocioso:
            _ev.emitir(_ev.Aviso(texto="interrupcion remota ignorada: no hay "
                                       "generacion en curso", origen="remoto"))
        else:
            _ev.emitir(_ev.Aviso(texto="generacion interrumpida desde el remoto",
                                 origen="remoto"))
    except Exception as exc:
        # el aviso es adorno; la interrupcion (abajo) es la sustancia — pero
        # que no salga se DICE (regla del repo: nada de degradacion muda)
        _aviso_degradado("remoto.interrupcion",
                         f"aviso no emitido ({type(exc).__name__}: {exc})")
    if ocioso:
        return
    _INTERRUPCION_PENDIENTE[0] = True
    raise KeyboardInterrupt("interrumpido desde el remoto")


def _interrupcion_recibida_nativa(tipo_evento: int) -> bool:
    """Cuerpo del handler NATIVO de consola (SetConsoleCtrlHandler, Windows).

    Windows lo invoca en un hilo NUEVO en el instante en que llega
    CTRL_BREAK_EVENT (1) / CTRL_C_EVENT (0), aunque el hilo principal este
    bloqueado en un recv() sin datos: es el unico sitio desde donde el Aviso
    puede salir EN EL ACTO. Aqui solo se avisa y se levanta la bandera; el
    corte real sigue siendo el KeyboardInterrupt del handler de Python
    (siguiente bytecode del hilo principal). Devuelve False SIEMPRE para que
    la cadena siga hasta el handler del CRT, que es el que convierte el
    evento en SIGBREAK/SIGINT y dispara el handler de Python: devolver True
    aqui se COMERIA la senal y el turno no se cortaria nunca."""
    try:
        if tipo_evento not in (0, 1):
            return False
        if _EN_PROMPT[0]:
            return False        # ocioso: el handler de Python dira 'ignorada'
        _INTERRUPCION_PENDIENTE[0] = True
        from cognia.ux import events as _ev
        _ev.emitir(_ev.Aviso(texto="interrupcion recibida; se aplica al terminar "
                                   "la llamada en curso", origen="remoto"))
    except Exception as exc:
        try:
            _aviso_degradado("remoto.interrupcion",
                             f"handler nativo: {type(exc).__name__}: {exc}")
        except Exception as exc2:
            # hilo del sistema y el avisador tambien roto: ultimo canal
            # posible, stderr crudo (jamas lanzar desde un ctrl handler)
            try:
                sys.stderr.write(f"[remoto.interrupcion] handler nativo: {exc!r}; "
                                 f"y _aviso_degradado fallo: {exc2!r}\n")
            except Exception:
                return False
    return False


def _instalar_ctrl_handler_nativo() -> bool:
    """Registra _interrupcion_recibida_nativa con SetConsoleCtrlHandler (solo
    Windows). Se registra DESPUES de que Python ya tiene el suyo (el CRT lo
    instala con el primer signal()), y Windows llama a los handlers en orden
    LIFO: el nuestro corre primero, avisa, y al devolver False pasa el turno
    al del CRT. True si quedo instalado."""
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes
        proto = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.DWORD)
        cb = proto(lambda tipo: bool(_interrupcion_recibida_nativa(int(tipo))))
        k32 = ctypes.windll.kernel32
        k32.SetConsoleCtrlHandler.argtypes = [proto, wintypes.BOOL]
        k32.SetConsoleCtrlHandler.restype = wintypes.BOOL
        if not k32.SetConsoleCtrlHandler(cb, True):
            _aviso_degradado("remoto.interrupcion",
                             f"SetConsoleCtrlHandler fallo (GetLastError "
                             f"{ctypes.get_last_error()}); el aviso inmediato "
                             "no saldra, la interrupcion sigue funcionando")
            return False
        _CTRL_HANDLER_NATIVO[0] = cb      # sin referencia viva, el GC lo mata
        return True
    except Exception as exc:
        _aviso_degradado("remoto.interrupcion",
                         f"handler nativo no instalado ({type(exc).__name__}: "
                         f"{exc}); el aviso inmediato no saldra")
        return False


def _repl_iteracion_interrumpida() -> bool:
    """Que hacer con un KeyboardInterrupt que llego al bucle del REPL desde
    DENTRO de una iteracion (fuera de los guards finos). Bajo COGNIA_REMOTO
    es la senal del movil: se dice y se sigue (True = `continue`). En local
    es Ctrl-C a mitad de un turno sin guard fino (la investigacion previa,
    el enrutador por inferencia, un slash largo): mismo contrato que el
    fast-path — 'turno cortado', el REPL sigue vivo (True). Solo devuelve
    False, y el bucle se cierra, si el turno pidio salir de verdad (no hay
    hoy tal caso: Ctrl-C doble vive en _get_input, que tiene su propio
    except). Baja la bandera cooperativa: el turno ya se corto."""
    _INTERRUPCION_PENDIENTE[0] = False
    remoto = os.environ.get("COGNIA_REMOTO", "").strip() == "1"
    print()
    if remoto:
        _print_line("[warn_cl]generacion interrumpida desde el remoto: turno "
                    "cortado. El REPL sigue vivo; /salir para salir.[/warn_cl]")
    else:
        _print_line("[warn_cl]Ctrl-C: turno cortado. El REPL sigue vivo; "
                    "/salir para salir.[/warn_cl]")
    return True


def _instalar_interrupcion_remota() -> str:
    """Instala el handler si COGNIA_REMOTO=1. Devuelve el nombre de la senal
    instalada ('SIGBREAK' | 'SIGINT') o '' (fuera del remoto, sin la senal en
    esta plataforma, o fuera del hilo principal: signal.signal lanza
    ValueError ahi y se avisa degradado).

    Windows: el servidor remoto crea el REPL con CREATE_NEW_PROCESS_GROUP y
    manda CTRL_BREAK_EVENT, que el CRT entrega como SIGBREAK. Medido
    2026-08-24 (scratch parent.py, 4 escenarios): llega con el servidor en
    consola, desacoplado (DETACHED_PROCESS) y con consola nueva oculta.
    POSIX: start_new_session + SIGINT, que Python ya entrega como
    KeyboardInterrupt por defecto; se instala igual para que el Aviso y el
    guard de _EN_PROMPT apliquen tambien alla."""
    if os.environ.get("COGNIA_REMOTO", "").strip() != "1":
        return ""
    import signal as _sg
    nombre = "SIGBREAK" if hasattr(_sg, "SIGBREAK") else "SIGINT"
    sig = getattr(_sg, nombre, None)
    if sig is None:
        return ""
    try:
        _sg.signal(sig, _interrupcion_remota_handler)
    except (ValueError, OSError) as exc:
        _aviso_degradado("remoto.interrupcion",
                         f"no pude instalar {nombre}: {exc}; el movil no "
                         "podra interrumpir esta sesion")
        return ""
    # DESPUES del de Python (orden LIFO de Windows: el nativo corre primero y
    # cede). Solo avisa en el acto y levanta la bandera; si no se instala, la
    # interrupcion sigue funcionando (con el aviso tardio de siempre).
    _instalar_ctrl_handler_nativo()
    return nombre


def _unir_continuacion(acumulado: str, siguiente: str, separador: str) -> str:
    """'hola \\' + 'mundo' -> 'hola<sep>mundo': la MISMA regla que la rama
    con PromptSession de _get_input (que une con ' ')."""
    return acumulado[:-1].rstrip() + separador + siguiente


def _leer_con_continuacion(primera: str, leer, separador: str = " ") -> str:
    """Continuacion oficial del REPL ('linea que termina en \\ sigue en la
    siguiente') para el modo input() PELADO (stdin en pipe: el remoto, los
    scripts). Antes solo la tenia la rama con PromptSession, asi que el
    servidor remoto no tenia forma de mandar un mensaje multilinea como UNA
    entrada: escribia el texto con sus saltos y el REPL lo despachaba como N
    mensajes (roto y sin test hasta 2026-08-24).

    `leer()` devuelve la siguiente linea cruda (input()); si levanta EOFError
    a mitad, se devuelve lo acumulado en vez de perderlo (un pipe que se
    cierra tras 'a \\' entrega 'a', no nada). `separador`: ' ' como el prompt
    rico; bajo COGNIA_REMOTO '\\n', porque ahi cada salto lo escribio el
    usuario en un textarea y es CONTENIDO (un bloque de codigo pegado en el
    movil se aplastaria a una linea con ' '). Con '\\n' las lineas de
    continuacion conservan su sangria (solo rstrip); con ' ' se recortan
    enteras, como en el prompt rico."""
    linea = primera
    while linea.endswith("\\"):
        try:
            siguiente = leer()
        except EOFError:
            return linea[:-1].rstrip()
        siguiente = siguiente.rstrip() if separador == "\n" else siguiente.strip()
        linea = _unir_continuacion(linea, siguiente, separador)
    return linea


def _remoto_stream_vivo() -> bool:
    """True cuando el fast-path de chat NO debe pintar la prosa del stream:
    bajo COGNIA_REMOTO=1 con TokenTexto pasando por el sink stdout
    (COGNIA_REMOTO_STREAM != '0').

    MEDIDO 2026-08-25 en la corrida real (e2e ii): el renderer no pinta bajo
    remoto (_sin_stream), pero el fast-path tiene su PROPIO FlujoSuave y con
    los TokenTexto pasando por el mismo stdout volvio EXACTAMENTE el
    entrelazado de 2026-08-09: '  Según los datos de hoy, @EV {"texto": " Ac"
    ...}'. Con esto el fast-path acumula en silencio y al terminar imprime la
    respuesta ENTERA y plana (_show_response respuesta_final): el movil pinta
    la burbuja viva con los deltas y la reemplaza por la final. Con
    COGNIA_REMOTO_STREAM=0 no hay deltas y se vuelve a pintar como siempre."""
    return (os.environ.get("COGNIA_REMOTO", "").strip() == "1"
            and os.environ.get("COGNIA_REMOTO_STREAM", "").strip() != "0")


def _separador_continuacion_simple() -> str:
    """'\\n' bajo COGNIA_REMOTO (los saltos son contenido), ' ' si no."""
    return "\n" if os.environ.get("COGNIA_REMOTO", "").strip() == "1" else " "


def _ctrlc_seguidos_idle() -> bool:
    """True si este Ctrl-C llega a menos de _VENTANA_CTRLC_S del anterior.

    Hasta 2026-08-18 un solo Ctrl-C en el prompt MATABA el REPL entero
    (cli.py: `except (EOFError, KeyboardInterrupt): break`). Con corridas en
    hilos eso pasa de molesto a destructivo, y ademas era incoherente: el
    fast-path de streaming y el camino articulado ya trataban Ctrl-C como
    "corta el turno, no la sesion". Dos seguidos siguen saliendo, que es lo
    que hace todo REPL."""
    ahora = time.monotonic()
    seguido = (ahora - _ULTIMO_CTRLC[0]) < _VENTANA_CTRLC_S
    _ULTIMO_CTRLC[0] = ahora
    return seguido


def _confirmar_accion(kind: str, detalle: str) -> bool:
    """Gate central de permisos: True = proceder. Respeta el modo vigente.

    Desde 2026-08-18 es un ENRUTADOR: decide QUIEN contesta, no como. La
    pregunta la responde SIEMPRE el dueno de la consola, porque un hilo que
    abre una Application de prompt_toolkit no vuelve nunca (medido: colgado
    para siempre con la vista abierta Y con solo el prompt abierto). Esta
    funcion es el ctx['confirm'] del agente y el agente ahora puede correr en
    un hilo: sin este enrutado, la primera accion sensible de un /hacer en
    segundo plano cuelga la corrida sin decir una palabra.
    """
    try:
        from cognia.console.permissions import needs_confirmation
        if not needs_confirmation(kind, detalle):
            return True
    except Exception as exc:
        # DENY ante cualquier fallo del clasificador. Esta funcion se inyecta
        # como ctx['confirm'] del agente: un import roto o un error de runtime
        # en cognia.console.permissions convertiria el default-deny del
        # sentinel (nivel CONFIRM) en "proceder sin preguntar". Los callers ya
        # degradan legible ante False ("Cancelado." / "no confirmado").
        logging.getLogger(__name__).warning(
            "Clasificador de permisos fallo (%s=%r): se deniega la accion "
            "por seguridad: %s", kind, detalle[:80], exc)
        return False
    if threading.current_thread() is not threading.main_thread():
        # El tiempo que el dueno tarda en contestar NO es tiempo de la tool:
        # con el deadline por tool (harness/timeout_tool, 120 s) y la espera
        # del permiso (600 s), el deadline vencia con la pregunta abierta, el
        # modelo recibia TOOL_TIMEOUT y el hilo huerfano ejecutaba el comando
        # al contestar 's' tarde (revision adversarial 2026-08-24). Fuera de
        # un worker del modulo la pausa es un no-op.
        with _pausa_deadline_tool():
            r = _preguntar_desde_hilo(kind, detalle)
            if r is not None:
                return r
            # Sin carril ni vista. Si este hilo es el WORKER de una tool con
            # deadline, quien espera esa tool (el principal en el despacho
            # inline: COGNIA_SIN_FONDO=1, /lazo, bucle legacy) es el dueno de
            # la consola: la pregunta sube a el. Recursivo a proposito: si el
            # que espera es otro worker, vuelve a subir hasta el principal.
            # Antes de esto, con el deadline TODA tool corria en un hilo y
            # todo comando CONFIRM se auto-denegaba sin que el dueno viera
            # la pregunta (revision adversarial 2026-08-24).
            hay, r = _pedir_al_llamador_tool(
                lambda: _confirmar_accion(kind, detalle))
            if hay:
                return bool(r)
        # No habia a quien delegar. Con un tty de por medio, preguntar aca
        # colgaria el hilo PARA SIEMPRE (medido), asi que se deniega — que es
        # el default del gate — y se dice por que. Sin tty (pipes, CI) el
        # input() de abajo funciona igual de bien desde un hilo: se sigue.
        try:
            from cognia.ux import selector as _sel
            if _sel.hay_tty():
                _aviso_degradado(
                    "cli.permiso.hilo_sin_carril",
                    f"{kind}: un hilo pidio permiso sin carril de fondo al que "
                    f"delegar; se deniega (preguntar aca colgaria el hilo)")
                return False
        except Exception:
            pass
    return _preguntar_en_consola(kind, detalle)


def _pausa_deadline_tool():
    """timeout_tool.pausa_deadline() o un no-op si el modulo no carga (se
    avisa: sin pausa el permiso sigue funcionando, solo vuelve el riesgo del
    deadline vencido con la pregunta abierta)."""
    try:
        from cognia.harness import timeout_tool as _tt
        return _tt.pausa_deadline()
    except Exception as exc:
        _aviso_degradado("cli.permiso.pausa_deadline",
                         f"sin pausa del deadline: {type(exc).__name__}: {exc}")
        return contextlib.nullcontext()


def _pedir_al_llamador_tool(fn):
    """timeout_tool.pedir_al_llamador(fn); (False, None) si el modulo no carga
    (se avisa: el permiso caera al deny de siempre, con su propio aviso)."""
    try:
        from cognia.harness import timeout_tool as _tt
        return _tt.pedir_al_llamador(fn)
    except Exception as exc:
        _aviso_degradado("cli.permiso.llamador",
                         f"no se pudo subir la pregunta al hilo que espera: "
                         f"{type(exc).__name__}: {exc}")
        return False, None


def _preguntar_en_consola(kind: str, detalle: str) -> bool:
    """La pregunta EN la consola. Solo la llama quien es dueno de ella.

    Es el cuerpo de _confirmar_accion de siempre, intacto: el texto
    '[permiso] ... (s/n) >' es contrato con los pipes y el e2e, el default es
    False y el spinner se para antes de abrir el selector."""
    # Con tty real: confirmacion con flechas ([Si]/[No] + atajos s/n).
    # default=False conserva la paridad con hoy (Enter vacio = NO ejecutar).
    # El input() de abajo queda INTACTO como fallback textual: el texto
    # '[permiso] ... (s/n) >' es lo que ven los pipes y el e2e — no cambiarlo.
    # REGLA: jamas abrir el selector con un rich Live/status activo; cuando
    # el agente pide permiso su spinner ya esta parado (ToolInicio aun no
    # arranco o ToolFin lo cerro), pero si un caller nuevo confirma dentro
    # de un status debe pararlo antes.
    try:
        from cognia.ux import selector as _selector
        if _selector.hay_tty():
            # Parar el spinner del renderer ANTES de abrir la Application:
            # este confirm es el ctx['confirm'] que el sentinel invoca DENTRO
            # de una tool en ejecucion (status girando) — prompt_toolkit y
            # rich status a la vez corrompen el terminal (revision 2026-08-10).
            try:
                from cognia.ux import renderer as _rmod
                if _rmod._renderer is not None:
                    _rmod._renderer._parar_status()
            except Exception:
                pass
            return _selector.confirmar(
                f"[permiso] {detalle[:80]} — ejecutar?", default=False)
    except Exception:
        pass  # cualquier fallo del selector degrada al input() de siempre
    try:
        resp = input(f"[permiso] {detalle[:80]} — ejecutar? (s/n) > ").strip().lower()
    except (EOFError, KeyboardInterrupt):
        return False
    return resp in ("s", "si", "y", "yes")


